/** Explicit local Chrome check; intercepted synthetic routes only, no product service or credentials.
 * Run: node --test tests/fixtures/xanthil-desktop/browser-workbench-ui-check.mjs
 * Requires an already installed Chrome (playwright-core does not install it).
 */
import assert from 'node:assert/strict';
import test from 'node:test';
import {chromium} from 'playwright-core';
import {readFile} from 'node:fs/promises';
const root=new URL('../../../',import.meta.url);
async function scenario(options,check){const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage(),calls=[];let fail=options.fail,control=options.readonly?null:'synthetic-control',current='p',createdTask=null,projects=[{project_id:'p',display_name:'会员分析'},{project_id:'p2',display_name:'另一项目'}];page.setDefaultTimeout(4000);
await page.route('**/*',async route=>{const req=route.request(),path=new URL(req.url()).pathname,payload=req.postData()?JSON.parse(req.postData()):null;let body,type='application/json',status=200;if(path.startsWith('/v1/'))calls.push({path,payload});
if(path==='/'){type='text/html';body=`<html lang="zh-CN"><meta charset="utf-8"><div id="app"></div><script type="module">import {startServiceWorkspace} from '/workspace.mjs';await startServiceWorkspace({control:${JSON.stringify(control)}});</script></html>`;}
else if(['/workspace.mjs','/client.mjs','/styles.css'].includes(path)){body=await readFile(new URL('apps/browser'+path,root));type=path.endsWith('.css')?'text/css':'text/javascript';}
else if(path==='/assets/logo.png'){body=await readFile(new URL('apps/desktop/assets/juanerai-logo-slogan.png',root));type='image/png';}
else if(path==='/v1/projects')body=JSON.stringify({projects,current});
else if(path==='/v1/projects/select'){current=payload.project_id??'new-'+projects.length;if(payload.name)projects.push({project_id:current,display_name:payload.name});body=JSON.stringify({control:'synthetic-control'});}
else if(path==='/v1/settings'){if(payload?.operation==='refresh'&&['refresh','refresh403'].includes(fail)){status=fail==='refresh403'?403:503;body='{}';}else body=JSON.stringify({ok:true,value:{configured:true,state:'ready'}});}
else if(path==='/v1/session')body=JSON.stringify({owned:true,generation:1});
else if(path==='/v1/control'){control='new-control';body=JSON.stringify({control});}
else if(path==='/v1/model-policy')body=JSON.stringify({available:true,sha256:'policy',policy:{model:'synthetic'}});
else if(path==='/v1/tasks'&&payload){createdTask=options.creation==='recorded'?{task_id:'t',question:payload.question,status:'idle'}:null;if(options.creation==='rejected')return route.fulfill({status:400,contentType:'application/json',body:'{}'});return route.abort('failed');}
else if(path.startsWith('/v1/commands/'))body=JSON.stringify(createdTask?{kind:'task_created',task_id:'t'}:null);
else if(path==='/v1/tasks')body=JSON.stringify({tasks:createdTask?[createdTask]:options.task?[{task_id:'t',question:'合成问题',status:'waiting'}]:[]});
else if(path==='/v1/tasks/t')body=JSON.stringify({question:'合成问题',task:{task_id:'t',epoch:0,row_version:1,status:'waiting',reviews:[]},case:{project:{display_name:'会员分析'},revision:{state:'Draft'},reports:[],findings:[]},model:{current:true,answerable:true,question:'请补充金额单位',execution_id:'q'},operations:{totals:{calls:0,local_runs:0,unresolved:0}}});
else throw Error('unexpected route '+path);
if(path===fail){status=503;body='{}';}return route.fulfill({status,contentType:type,body});});
await page.goto('https://workbench.invalid/');await page.locator('#current-project').waitFor();await check({page,calls,setFailure:value=>{fail=value;}});
}finally{await browser.close();}}
async function settled(page){await page.evaluate(()=>new Promise(requestAnimationFrame));}
test('BF-UI05/06 shell synchronizes after entry and inner takeover without replacing drafts',async()=>{for(const readonly of [false,'inner','outer'])await scenario({readonly},async({page,calls})=>{await page.locator(readonly==='outer'?'#service-takeover':'#current-project').click();await page.locator('#question').waitFor();await page.locator('#question').fill('必须保留的问题');if(readonly==='inner'){await page.locator('#take-control').click();await page.waitForFunction(()=>!document.querySelector('#take-control'));}await settled(page);assert.equal(await page.locator('#project-name').isDisabled(),false);assert.deepEqual(await page.locator('[data-project]').evaluateAll(nodes=>nodes.map(n=>n.disabled)),[false,false]);assert.equal(await page.locator('#account-settings').isDisabled(),false);assert.equal(await page.getByText('本页只读，其他页面正在操作。').count(),0);assert.equal(await page.locator('#question').inputValue(),'必须保留的问题');assert.equal(calls.filter(c=>c.payload?.operation==='test').length,0);});});
test('BF-UI04/06 initial policy/list/task failure presents read-only retry and preserves draft',async()=>{for(const path of ['/v1/model-policy','/v1/tasks','/v1/tasks/t'])await scenario({fail:path,task:path.endsWith('/t')},async({page,calls,setFailure})=>{await page.locator('#entry-question').fill('不要丢失的问题');await page.locator('#current-project').click();await settled(page);await page.locator('#retry-workbench').waitFor();assert.match(await page.locator('body').innerText(),/暂时无法打开分析/);setFailure(null);await page.locator('#retry-workbench').click();await page.locator(path.endsWith('/t')?'#clarification-reply':'#question').waitFor();if(!path.endsWith('/t'))assert.equal(await page.locator('#question').inputValue(),'不要丢失的问题');assert.equal(calls.filter(c=>c.path==='/v1/projects/select').length,0);assert.equal(calls.filter(c=>c.payload?.operation==='test').length,0);});});
test('BF-UI04/05 failed access refresh clears stale ready and never probes or deletes',async()=>{for(const fail of ['refresh','refresh403'])await scenario({fail},async({page,calls})=>{await page.locator('#current-project').click();await page.locator('#question').waitFor();await settled(page);assert.doesNotMatch(await page.locator('#ai-status').innerText(),/已就绪/);assert.match(await page.locator('#service-notice').innerText(),/暂时无法确认 AI|本页只读/);assert.equal(calls.filter(c=>['test','save','delete'].includes(c.payload?.operation)).length,0);assert.equal(await page.locator('#provider-api-key').count(),0);});});
test('BF-UI05/06 inner takeover keeps clarification draft and switching read failure keeps content with no duplicate selection',async()=>{await scenario({readonly:true,task:true},async({page,calls,setFailure})=>{await page.locator('#current-project').click();await page.locator('#clarification-reply').waitFor();await page.locator('#take-control').click();await page.waitForFunction(()=>!document.querySelector('#take-control'));await page.locator('#clarification-reply').fill('金额按元计算，保留这段说明');await page.locator('#account-settings').click();await page.locator('#close-settings').click();assert.equal(await page.locator('#clarification-reply').inputValue(),'金额按元计算，保留这段说明');await page.locator('.project-picker summary').click();setFailure('/v1/tasks');await page.locator('[data-project="p2"]').click();await page.locator('#retry-workbench').waitFor();assert.equal(await page.locator('#clarification-reply').inputValue(),'金额按元计算，保留这段说明');assert.equal(await page.locator('#clarification-reply').isDisabled(),true);assert.equal(calls.filter(c=>c.path==='/v1/projects/select').length,1);setFailure(null);await page.locator('#retry-workbench').click();await page.waitForFunction(()=>!document.querySelector('#retry-workbench'));assert.equal(calls.filter(c=>c.path==='/v1/projects/select').length,1);await page.locator('[data-project="p"]').click();await page.waitForFunction(()=>document.querySelector('#clarification-reply')?.value==='金额按元计算，保留这段说明');assert.equal(await page.locator('#clarification-reply').inputValue(),'金额按元计算，保留这段说明');});});

test('BF-UI06 project identity and menu follow create/switch while task drafts remain project-local',async()=>{await scenario({},async({page,calls})=>{
 await page.locator('#project-name').fill('新建合成项目');await page.locator('#project-create button').click();await page.locator('#question').waitFor();assert.equal(await page.locator('.project-picker > summary').innerText(),'新建合成项目');
 await page.locator('.project-picker > summary').click();await page.locator('[data-project="p2"]').click();await settled(page);await page.waitForFunction(()=>!document.querySelector('#project-name').disabled);assert.equal(await page.locator('.project-picker > summary').innerText(),'另一项目');await page.locator('#question').fill('属于另一项目的草稿');
 await page.locator('#project-name').fill('第二个合成项目');await page.locator('#project-create button').click();await page.waitForFunction(()=>!document.querySelector('#project-name').disabled);assert.equal(await page.locator('.project-picker > summary').innerText(),'第二个合成项目');assert.equal(await page.locator('[data-project]').count(),4);assert.equal(await page.locator('[data-project="new-3"]').innerText(),'第二个合成项目');
 await page.locator('[data-project="p2"]').click();await page.waitForFunction(()=>document.querySelector('#question')?.value==='属于另一项目的草稿');assert.equal(await page.locator('.project-picker > summary').innerText(),'另一项目');assert.equal(calls.filter(c=>c.path==='/v1/projects/select').length,4);assert.equal(calls.filter(c=>['test','save'].includes(c.payload?.operation)).length,0);
 });});
test('BF-UI06 entry question belongs only to the first chosen project and survives A to B to A',async()=>{await scenario({},async({page,calls})=>{await page.locator('#entry-question').fill('只属于项目 A 的问题');await page.locator('#current-project').click();await page.locator('#question').waitFor();assert.equal(await page.locator('#question').inputValue(),'只属于项目 A 的问题');await page.locator('.project-picker > summary').click();await page.locator('[data-project="p2"]').click();await page.waitForFunction(()=>!document.querySelector('#project-name').disabled);assert.equal(await page.locator('#question').inputValue(),'');await page.locator('[data-project="p"]').click();await page.waitForFunction(()=>!document.querySelector('#project-name').disabled);assert.equal(await page.locator('#question').inputValue(),'只属于项目 A 的问题');await page.locator('#project-name').fill('全新空白项目');await page.locator('#project-create button').click();await page.waitForFunction(()=>!document.querySelector('#project-name').disabled);assert.equal(await page.locator('#question').inputValue(),'');assert.equal(calls.filter(c=>c.path==='/v1/tasks'&&c.payload).length,0);assert.equal(calls.filter(c=>['test','save'].includes(c.payload?.operation)).length,0);});});

test('BF-UI05/06 recovered saved task consumes its new draft; unknown or rejected receipt retains draft',async()=>{for(const creation of ['recorded','unknown','rejected'])await scenario({creation},async({page,calls})=>{await page.locator('#entry-question').fill('待确认的原问题');await page.locator('#current-project').click();await page.locator('#create-form button').click();await page.locator('#recover').waitFor();await page.locator('#recover').click();if(creation==='unknown')await page.getByText('尚未确认完成，继续保留并读回。',{exact:true}).waitFor();else await page.locator('#recover').waitFor({state:'detached'});if(creation==='recorded'){await page.locator('#new-task').click();assert.equal(await page.locator('#question').inputValue(),'');}else{assert.equal(await page.locator('#question').inputValue(),'待确认的原问题');assert.equal(await page.locator('#recover').count(),creation==='unknown'?1:0);}assert.equal(calls.filter(c=>c.path==='/v1/tasks'&&c.payload).length,1);assert.equal(calls.filter(c=>c.path==='/v1/projects/select').length,0);assert.equal(calls.filter(c=>['test','save','delete'].includes(c.payload?.operation)).length,0);});});
test('BF-UI01/06 live corrected question and clarification survive non-submitting mode renders',async()=>{await scenario({creation:'rejected'},async({page,calls})=>{await page.locator('#entry-question').fill('被拒绝的旧问题');await page.locator('#current-project').click();await page.locator('#create-form button').click();await page.locator('#recover').waitFor();await page.locator('#recover').click();await page.locator('#recover').waitFor({state:'detached'});await page.locator('#question').fill('现在修正后的问题');await page.locator('[data-mode="professional"]').click();assert.equal(await page.locator('#question').inputValue(),'现在修正后的问题');await page.locator('[data-mode="simple"]').click();assert.equal(await page.locator('#question').inputValue(),'现在修正后的问题');assert.equal(calls.filter(c=>c.path==='/v1/tasks'&&c.payload).length,1);});});
test('BF-UI04 live clarification survives mode and account view changes',async()=>{await scenario({task:true},async({page,calls})=>{await page.locator('#current-project').click();await page.locator('#clarification-reply').fill('刚输入的金额单位说明');await page.locator('[data-mode="professional"]').click();assert.equal(await page.locator('#clarification-reply').inputValue(),'刚输入的金额单位说明');await page.locator('#account-settings').click();await page.locator('#close-settings').click();assert.equal(await page.locator('#clarification-reply').inputValue(),'刚输入的金额单位说明');assert.equal(calls.filter(c=>c.path.endsWith('/clarification')).length,0);assert.equal(calls.filter(c=>['test','save','delete'].includes(c.payload?.operation)).length,0);});});
